"""SQLite-backed repository using append-only IntentStore for events/audit."""

from __future__ import annotations

import os
from typing import Any

from core.intent_store import IntentStore
from core.models import CustomerOutcome, Job, Outcome, Step
from core.repository import Repository


class SQLiteRepository(Repository):
    def __init__(self, db_path: str | None = None) -> None:
        if db_path is None:
            db_path = os.environ.get("AGENTIC_ODI_DB", os.path.expanduser("~/.agentic-odi/odi.db"))
        os.makedirs(os.path.dirname(db_path) or ".", exist_ok=True)
        self.store = IntentStore(db_path)
        # For compatibility with existing semantics, we also maintain a materialized
        # view in memory for fast reads (in-memory snapshot) - simple approach for now.
        self._load_snapshot()

    def _load_snapshot(self) -> None:
        self.jobs: dict[str, Job] = {}
        self.steps: dict[str, Step] = {}
        self.outcomes: dict[str, Outcome] = {}
        self.customer_outcomes: dict[str, CustomerOutcome] = {}
        for ev in self.store.get_stream():
            et = ev["type"]
            p = ev["payload"]
            if et == "JOB_CREATED":
                self.jobs[p["id"]] = Job.model_validate(p)
            elif et == "STEP_CREATED":
                self.steps[p["id"]] = Step.model_validate(p)
            elif et == "OUTCOME_CREATED":
                self.outcomes[p["id"]] = Outcome.model_validate(p)
            elif et == "CUSTOMER_OUTCOME_CREATED":
                self.customer_outcomes[p["id"]] = CustomerOutcome.model_validate(p)
            elif et == "CUSTOMER_OUTCOME_UPDATED":
                cid = p["id"]
                co = self.customer_outcomes.get(cid)
                if co is not None:
                    current = co.model_dump(exclude_unset=True)
                    current.update(p.get("updates", {}))
                    try:
                        self.customer_outcomes[cid] = co.model_validate(current)
                    except Exception:  # noqa: BLE001
                        pass
            elif et == "CUSTOMER_OUTCOME_DELETED":
                cid = p["id"]
                self.customer_outcomes.pop(cid, None)
        # also snapshot jobs/steps/outcomes? we emitted above

    def add_job(self, job: Job) -> Job:
        self.store.append("JOB_CREATED", job.model_dump())

"""External data connector CLI subcommands."""

from __future__ import annotations

import asyncio
from typing import Annotated

import typer
from connectors import (
    ConnectorConfig,
    ConnectorNotFoundError,
    ConnectorRegistry,
    DuplicateConnectorError,
    IngestSink,
    build_connector,
)

connectors_app = typer.Typer(help="Manage external data connectors.")
add_app = typer.Typer(help="Add a connector.")
connectors_app.add_typer(add_app, name="add")

ConfigOption = Annotated[
    str | None, typer.Option("--config", help="Path to the connectors config file")
]


def _registry(config_path: str | None) -> ConnectorRegistry:
    if config_path is None:
        return ConnectorRegistry()
    return ConnectorRegistry(config_path)


def _sink() -> IngestSink:
    return IngestSink()


def _get_config(name: str, config_path: str | None) -> ConnectorConfig:
    try:
        return _registry(config_path).get(name)
    except ConnectorNotFoundError as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc


@connectors_app.command("list")
def list_connectors(config: ConfigOption = None) -> None:
    """List configured connectors."""
    configs = _registry(config).list()
    if not configs:
        typer.echo("No connectors configured.")
        return
    for connector in configs:
        typer.echo(f"{connector.name}\t{connector.kind}\t{connector.enabled}")


@add_app.command("mcp")
def add_mcp(
    name: Annotated[str, typer.Option("--name", help="Connector name")],
    url: Annotated[str, typer.Option("--url", help="MCP server URL")],
    tool: Annotated[list[str] | None, typer.Option("--tool", help="Tool name to ingest")] = None,
    config: ConfigOption = None,
) -> None:
    """Add an MCP connector."""
    connector_config = ConnectorConfig(
        name=name,
        kind="mcp",
        settings={"url": url, "tools": tool or []},
    )
    try:
        _registry(config).add(connector_config)
    except DuplicateConnectorError as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    typer.echo(f"Added connector {name!r}.")


@connectors_app.command("health")
def health(
    name: Annotated[str, typer.Option("--name", help="Connector name")],
    config: ConfigOption = None,
) -> None:
    """Check that a connector is reachable."""
    connector_config = _get_config(name, config)
    status = asyncio.run(build_connector(connector_config, _sink()).health())
    typer.echo(f"{'ok' if status.ok else 'not ok'}: {status.detail}")
    if not status.ok:
        raise typer.Exit(code=1)


@connectors_app.command("ingest")
def ingest(
    name: Annotated[str, typer.Option("--name", help="Connector name")],
    dump: Annotated[
        str | None, typer.Option("--dump", help="Path to dump ingested records as JSON")
    ] = None,
    config: ConfigOption = None,
) -> None:
    """Ingest data from a connector."""
    connector_config = _get_config(name, config)
    sink = _sink()
    batch = asyncio.run(build_connector(connector_config, sink).ingest())
    typer.echo(
        f"{batch.connector_name}: {len(batch.records)} record(s), {len(batch.errors)} error(s)"
    )
    if dump is not None:
        sink.dump(dump)
